def from_pov(self, from_node):
    if not self._contains(self, from_node):
        raise ValueError("Tree could not be reoriented")
    return self._reconstruct(self, from_node, None)

def _contains(self, node, label):
    if node.label == label:
        return True
    return any(self._contains(child, label) for child in node.children)

def _reconstruct(self, node, from_node, parent):
    children = []
    for child in node.children:
        if child.label == from_node:
            continue
        children.append(self._reconstruct(child, from_node, node))
    if parent is not None:
        children.append(self._reconstruct(parent, from_node, node))
    return Tree(node.label, children)

def path_to(self, from_node, to_node):
    tree = self.from_pov(from_node)
    path = []

    def dfs(node):
        path.append(node.label)
        if node.label == to_node:
            return True
        for child in node.children:
            if dfs(child):
                return True
        path.pop()
        return False

    if not dfs(tree):
        raise ValueError("No path found")
    return path

