def from_pov(self, from_node):
    path = self._find_path(self, from_node)
    if path is None:
        raise ValueError("Tree could not be reoriented")
    parents = {}
    self._build_parents(self, parents)
    next_on_path = {}
    for i, node in enumerate(path):
        next_on_path[node] = path[i + 1] if i + 1 < len(path) else None
    return self._reconstruct(path[-1], parents, next_on_path)

def _find_path(self, node, label, trail=None):
    trail = trail + [node] if trail is not None else [node]
    if node.label == label:
        return trail
    for child in node.children:
        found = self._find_path(child, label, trail)
        if found is not None:
            return found
    return None

def _build_parents(self, node, parents):
    for child in node.children:
        parents[child] = node
        self._build_parents(child, parents)

def _reconstruct(self, node, parents, next_on_path):
    # The re-oriented parent of a node is the next hop toward the new
    # root: the following node on the path for nodes on the path, and
    # the original parent for every other node.
    skip = next_on_path[node] if node in next_on_path else parents.get(node)
    children = []
    for child in node.children:
        if child is not skip:
            children.append(self._reconstruct(child, parents, next_on_path))
    parent = parents.get(node)
    if parent is not None and parent is not skip:
        children.append(self._reconstruct(parent, parents, next_on_path))
    return Tree(node.label, children)

